import java.util.*;

class Solution {
    public int minCostConnectPoints(int[][] points) {
        int n = points.length;
        boolean[] visited = new boolean[n];
        int[] minDist = new int[n];
        Arrays.fill(minDist, Integer.MAX_VALUE);
        minDist[0] = 0;

        int total = 0;
        for (int added = 0; added < n; added++) {
            int next = -1;
            for (int i = 0; i < n; i++) {
                if (!visited[i] && (next == -1 || minDist[i] < minDist[next])) {
                    next = i;
                }
            }

            visited[next] = true;
            total += minDist[next];
            for (int j = 0; j < n; j++) {
                if (!visited[j]) {
                    int dist = Math.abs(points[next][0] - points[j][0])
                            + Math.abs(points[next][1] - points[j][1]);
                    if (dist < minDist[j]) {
                        minDist[j] = dist;
                    }
                }
            }
        }
        return total;
    }
}

import java.util.*;

class Solution {
    public int minCostConnectPoints(int[][] points) {
        int n = points.length;
        List<int[]> edges = new ArrayList<>(n * (n - 1) / 2);
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int weight = Math.abs(points[i][0] - points[j][0])
                        + Math.abs(points[i][1] - points[j][1]);
                edges.add(new int[]{weight, i, j});
            }
        }
        edges.sort(Comparator.comparingInt(edge -> edge[0]));

        DSU dsu = new DSU(n);
        int total = 0;
        int used = 0;
        for (int[] edge : edges) {
            if (used == n - 1) {
                break;
            }
            if (dsu.union(edge[1], edge[2])) {
                total += edge[0];
                used++;
            }
        }
        return total;
    }

    private static final class DSU {
        private final int[] parent;
        private final int[] rank;

        DSU(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        boolean union(int a, int b) {
            int rootA = find(a);
            int rootB = find(b);
            if (rootA == rootB) {
                return false;
            }
            if (rank[rootA] < rank[rootB]) {
                int tmp = rootA;
                rootA = rootB;
                rootB = tmp;
            }
            parent[rootB] = rootA;
            if (rank[rootA] == rank[rootB]) {
                rank[rootA]++;
            }
            return true;
        }
    }
}

import java.util.*;

class Solution {
    public int minCostConnectPoints(int[][] points) {
        int n = points.length;
        boolean[] visited = new boolean[n];
        PriorityQueue<int[]> heap = new PriorityQueue<>(Comparator.comparingInt(edge -> edge[0]));
        heap.offer(new int[]{0, 0});

        int total = 0;
        int added = 0;
        while (added < n) {
            int[] edge = heap.poll();
            int cost = edge[0];
            int point = edge[1];
            if (visited[point]) {
                continue;
            }

            visited[point] = true;
            total += cost;
            added++;
            for (int next = 0; next < n; next++) {
                if (!visited[next]) {
                    int dist = Math.abs(points[point][0] - points[next][0])
                            + Math.abs(points[point][1] - points[next][1]);
                    heap.offer(new int[]{dist, next});
                }
            }
        }
        return total;
    }
}

import java.util.*;

class Solution {
    public int minCostConnectPoints(int[][] points) {
        int n = points.length;
        DSU dsu = new DSU(n);
        int components = n;
        int total = 0;

        while (components > 1) {
            int[] bestU = new int[n];
            int[] bestV = new int[n];
            int[] bestW = new int[n];
            Arrays.fill(bestW, Integer.MAX_VALUE);

            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < n; j++) {
                    int rootI = dsu.find(i);
                    int rootJ = dsu.find(j);
                    if (rootI == rootJ) {
                        continue;
                    }
                    int weight = Math.abs(points[i][0] - points[j][0])
                            + Math.abs(points[i][1] - points[j][1]);
                    if (weight < bestW[rootI]) {
                        bestU[rootI] = i;
                        bestV[rootI] = j;
                        bestW[rootI] = weight;
                    }
                    if (weight < bestW[rootJ]) {
                        bestU[rootJ] = i;
                        bestV[rootJ] = j;
                        bestW[rootJ] = weight;
                    }
                }
            }

            for (int root = 0; root < n; root++) {
                if (bestW[root] != Integer.MAX_VALUE && dsu.union(bestU[root], bestV[root])) {
                    total += bestW[root];
                    components--;
                }
            }
        }
        return total;
    }

    private static final class DSU {
        private final int[] parent;
        private final int[] rank;

        DSU(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        boolean union(int a, int b) {
            int rootA = find(a);
            int rootB = find(b);
            if (rootA == rootB) {
                return false;
            }
            if (rank[rootA] < rank[rootB]) {
                int tmp = rootA;
                rootA = rootB;
                rootB = tmp;
            }
            parent[rootB] = rootA;
            if (rank[rootA] == rank[rootB]) {
                rank[rootA]++;
            }
            return true;
        }
    }
}
